mapper.select:
select od.id as orderDetailId, od.`type`, od.billing_item_id as billingItemId, od.price, od.quantity, od.receivable_amount as receivableAmount, od.tooth_bit as toothBit, od.executor_id as executorId, od.remarks from order_detail od
and od.order_record_id = #{orderRecordId}
and od.source_type = #{sourceType}

SELECT SUM( od.quantity ) FROM order_detail od
AND od.inservice = 1 AND od.type = 0 AND od.order_record_id IN ( SELECT id FROM order_record WHERE `status` = 2 )
AND DATE_FORMAT( od.crt_time, '%Y-%m' ) = #{query.queryDate}
AND DATE_FORMAT( od.crt_time, '%Y' ) = #{query.queryDate}
AND od.billing_item_id IN
#{item}
AND od.org_id IN
#{item}

SELECT od.billing_item_id AS tariffItemId, bt.`name` AS tariffItemName, SUM( od.quantity ) AS completedAmount FROM ( SELECT od.billing_item_id, od.quantity FROM order_detail od,( SELECT id FROM order_record WHERE `status` = 2 ) ord
AND od.inservice = 1 AND od.order_record_id = ord.id AND od.type = 0
AND DATE_FORMAT( od.crt_time, '%Y-%m' ) = #{query.queryDate}
AND DATE_FORMAT( od.crt_time, '%Y' ) = #{query.queryDate}
AND od.billing_item_id IN
#{item}
AND od.org_id IN
#{item}
) od LEFT JOIN base_tariff bt ON od.billing_item_id = bt.id GROUP BY od.billing_item_id

select count(1) from order_detail od join order_record ord on od.order_record_id = ord.id


        and od.org_id in

            #{orgId}





            and DATE_FORMAT( od.crt_time, '%Y-%m-%d') >= #{form.startDate}


            and DATE_FORMAT( od.crt_time, '%Y-%m-%d') <= #{form.endDate}




            and DATE_FORMAT( od.crt_time, '%Y-%m') >= #{form.startDate}


            and DATE_FORMAT( od.crt_time, '%Y-%m') <= #{form.endDate}




            and DATE_FORMAT( od.crt_time, '%Y') >= #{form.startDate}


            and DATE_FORMAT( od.crt_time, '%Y') <= #{form.endDate}


    and od.type = 0
    and ord.status = 2

select sum(od.quantity) as quantity,
od.org_id as orgId,
od.crt_time as crtTime,
od.billing_item_id as billingItemId
from order_record ord left join order_detail od on od.order_record_id = ord.id


        and od.org_id in

            #{orgId}




            and DATE_FORMAT( od.crt_time, '%Y-%m-%d') >= #{form.startDate}


            and DATE_FORMAT( od.crt_time, '%Y-%m-%d') <= #{form.endDate}




            and DATE_FORMAT( od.crt_time, '%Y-%m') >= #{form.startDate}


            and DATE_FORMAT( od.crt_time, '%Y-%m') <= #{form.endDate}




            and DATE_FORMAT( od.crt_time, '%Y') >= #{form.startDate}


            and DATE_FORMAT( od.crt_time, '%Y') <= #{form.endDate}


    and od.inservice = 1
    and od.type = 0
    and ord.status = 2

group by billingItemId

SELECT SUM( od.quantity ) FROM ( SELECT ord.`status`, od.org_id, od.quantity, od.type, od.billing_item_id, od.crt_time, od.inservice FROM order_detail od LEFT JOIN order_record ord ON od.order_record_id = ord.id ) od
AND od.inservice = 1 AND od.`status` = 2 AND od.`type` = 0
AND od.org_id = #{query.orgId}
AND od.billing_item_id IN
#{item}
AND DATE_FORMAT(od.crt_time, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(od.crt_time, '%Y-%m') <= #{query.endDate}

SELECT od.org_id as orgId, od.billing_item_id as billingItemId, SUM( od.quantity ) as quantity FROM ( SELECT ord.`status`, od.org_id, od.quantity, od.type, od.billing_item_id, od.crt_time, od.inservice FROM order_detail od LEFT JOIN order_record ord ON od.order_record_id = ord.id ) od
AND od.inservice = 1 AND od.`status` = 2 AND od.`type` = 0
AND od.org_id = #{query.orgId}
AND od.billing_item_id IN
#{item}
AND DATE_FORMAT(od.crt_time, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(od.crt_time, '%Y-%m') <= #{query.endDate}
group by od.org_id, od.billing_item_id

SELECT od.org_id AS orgId, bt.type, bt.categoryId, IFNULL(SUM(od.price*od.quantity),0) amount FROM order_detail od INNER JOIN bill_record br on br.order_record_id=od.order_record_id INNER JOIN ( SELECT id,tariff_category_id AS categoryId,0 AS type FROM base_tariff WHERE inservice=1 UNION ALL SELECT id,oral_tariff_category_id AS categoryId,1 AS type FROM base_oral_tariff WHERE inservice=1 ) bt on bt.id = od.billing_item_id and bt.type=od.type WHERE NOT EXISTS ( SELECT behdr.associate_record_id FROM bill_exception_handle_record behr LEFT JOIN bill_exception_handle_detail_record behdr ON behr.id = behdr.bill_handle_record_id WHERE operate_type = 2
AND DATE_FORMAT(behr.crt_time, '%Y-%m') = #{query.queryDate}
AND behdr.associate_record_id=br.order_record_id )
AND br.org_id IN
#{item}
AND DATE_FORMAT(br.crt_time, '%Y-%m') = #{query.queryDate}
GROUP BY od.org_id, bt.type, bt.categoryId

SELECT od.org_id AS orgId, od.order_record_id AS orderRecordId, od.type, od.billing_item_id AS billingItemId, od.receivable_amount AS receivableAmount FROM order_detail od INNER JOIN bill_pay_record bpr ON od.order_record_id=bpr.order_record_id INNER JOIN bill_record br ON od.order_record_id=br.order_record_id
AND bpr.id NOT IN
#{item}
and DATE_FORMAT(bpr.crt_time, '%Y-%m') = #{query.queryDate} and DATE_FORMAT(br.crt_time, '%Y-%m') = #{query.queryDate}
AND br.org_id IN
#{item}
